	out, err := runner.Run(ctx, "gh", "api", "user/orgs", "--jq", ".[].login")
	if err != nil {
		return nil, err
	}
	var orgs []string
	for _, line := range strings.Split(out, "\n") {
		line = strings.TrimSpace(line)
		if line != "" {
			orgs = append(orgs, line)
		}
	}
	sort.Strings(orgs)
	return orgs, nil
}

