53	// fakeRunner is a test seam for bootstrapRunner. Each (name, args[0]) pair
54	// maps to a response.
55	type fakeRunner struct {
56		mu          sync.Mutex
57		responses   map[string]fakeResponse
58		interactive map[string]error
59		calls       []fakeCall
60	}
61	
62	type fakeResponse struct {
63		stdout string
64		err    error
65	}
66	
67	type fakeCall struct {
68		dir  string
69		name string
70		args []string
71	}
72	
73	func newFakeRunner() *fakeRunner {
74		return &fakeRunner{
75			responses:   make(map[string]fakeResponse),
76			interactive: make(map[string]error),
77		}
78	}
79	
80	func (f *fakeRunner) key(name string, args []string) string {
81		return name + " " + strings.Join(args, " ")
82	}
83	
84	func (f *fakeRunner) set(name string, args []string, stdout string, err error) {
85		f.mu.Lock()
86		defer f.mu.Unlock()
87		f.responses[f.key(name, args)] = fakeResponse{stdout: stdout, err: err}
88	}
89	
90	func (f *fakeRunner) setInteractive(name string, args []string, err error) {
91		f.mu.Lock()
92		defer f.mu.Unlock()
93		f.interactive[f.key(name, args)] = err
94	}
95	
96	func (f *fakeRunner) lookup(name string, args []string) (fakeResponse, bool) {
97		f.mu.Lock()
98		defer f.mu.Unlock()
99		r, ok := f.responses[f.key(name, args)]
100		return r, ok
101	}
