57	// fakeRunner is a test seam for bootstrapRunner. Each (name, args[0]) pair
58	// maps to a response.
59	type fakeRunner struct {
60		mu          sync.Mutex
61		responses   map[string]fakeResponse
62		interactive map[string]error
63		calls       []fakeCall
64	}
65	
66	type fakeResponse struct {
67		stdout string
68		err    error
69	}
70	
71	type fakeCall struct {
72		dir  string
73		name string
74		args []string
75	}
76	
77	func newFakeRunner() *fakeRunner {
78		return &fakeRunner{
79			responses:   make(map[string]fakeResponse),
80			interactive: make(map[string]error),
81		}
82	}
83	
84	func (f *fakeRunner) key(name string, args []string) string {
85		return name + " " + strings.Join(args, " ")
86	}
87	
88	func (f *fakeRunner) set(name string, args []string, stdout string, err error) {
89		f.mu.Lock()
90		defer f.mu.Unlock()
91		f.responses[f.key(name, args)] = fakeResponse{stdout: stdout, err: err}
92	}
93	
94	func (f *fakeRunner) setInteractive(name string, args []string, err error) {
95		f.mu.Lock()
96		defer f.mu.Unlock()
97		f.interactive[f.key(name, args)] = err
98	}
99	
100	func (f *fakeRunner) lookup(name string, args []string) (fakeResponse, bool) {
101		f.mu.Lock()
102		defer f.mu.Unlock()
103		r, ok := f.responses[f.key(name, args)]
104		return r, ok
105	}
106	
107	func (f *fakeRunner) record(dir, name string, args []string) {
108		f.mu.Lock()
109		defer f.mu.Unlock()
110		f.calls = append(f.calls, fakeCall{dir: dir, name: name, args: args})
111	}
112	
113	func (f *fakeRunner) Run(_ context.Context, name string, args ...string) (string, error) {
114		f.record("", name, args)
115		if r, ok := f.lookup(name, args); ok {
116			return r.stdout, r.err
117		}
118		return "", fmt.Errorf("fakeRunner: unexpected call %s %v", name, args)
119	}
120	
121	func (f *fakeRunner) RunInDir(_ context.Context, dir, name string, args ...string) (string, error) {
122		f.record(dir, name, args)
123		if r, ok := f.lookup(name, args); ok {
124			return r.stdout, r.err
125		}
126		return "", fmt.Errorf("fakeRunner: unexpected call in %s: %s %v", dir, name, args)
127	}
128	
129	func (f *fakeRunner) RunInteractive(_ context.Context, dir, name string, args ...string) error {
130		f.record(dir, name, args)
131		f.mu.Lock()
132		defer f.mu.Unlock()
133		return f.interactive[f.key(name, args)]
134	}
